<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientRegistrationAccessVO;

trait TrustedClientRegistrationAccessAttributeHolder
{
    protected TrustedClientRegistrationAccessVO|string|null $registrationAccess = null;
    protected bool $registrationAccessAssigned = false;

    public function getRegistrationAccessOrDefault(?TrustedClientRegistrationAccessVO $registrationAccess): ?TrustedClientRegistrationAccessVO
    {
        return $this->registrationAccessAssigned ? ($this->registrationAccess !== null ? TrustedClientRegistrationAccessVO::from($this->registrationAccess) : null) : $registrationAccess;
    }
    public function registrationAccess(TrustedClientRegistrationAccessVO|string|null $registrationAccess): static
    {
        $this->registrationAccess = $registrationAccess;
        $this->registrationAccessAssigned = true;
        return $this;
    }
    public function getRegistrationAccess(): ?string
    {
        return $this->registrationAccess instanceof TrustedClientRegistrationAccessVO ? $this->registrationAccess->value() : $this->registrationAccess;
    }
    public function isRegistrationAccessAssigned(): bool
    {
        return $this->registrationAccessAssigned;
    }
    public function writeRegistrationAccessTo(mixed $att): void
    {
        if ($this->registrationAccessAssigned) {
            $att->registrationAccess($this->registrationAccess);
        }
    }
    public function readRegistrationAccessFrom(mixed $att): void
    {
        if ($att->isRegistrationAccessAssigned()) {
            $registrationAccess = $att->getRegistrationAccess();
            $this->registrationAccess($registrationAccess);
        }
    }
    public function unsetRegistrationAccess(): static
    {
        $this->registrationAccessAssigned = false;
        return $this;
    }
    protected function withDefaultRegistrationAccess(): void
    {
    }
    protected function withAssertedRegistrationAccessRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->registrationAccessAssigned = $this->registrationAccessAssigned) {
            $value->registrationAccess = TrustedClientRegistrationAccessVO::tryFrom($this->registrationAccess, $errorsList);
        }
    }
}
